-- Generated by generate-views.ts from public.replication_probe. Regenerate after a migration changes its columns.
CREATE OR REPLACE VIEW goodparty_data_catalog.gp_api_mirror_dms.replication_probe
COMMENT 'Current state of public.replication_probe: the latest change per primary key in dms_cdc_change, deletes removed. TOASTable columns an update left out are carried from the previous change.'
AS
WITH reload AS (
  SELECT max(reloaded_at) AS reloaded_at FROM goodparty_data_catalog.gp_api_mirror_dms.dms_cdc_reload WHERE source_table = 'replication_probe'
),
changes AS (
  SELECT c.pk, c.op, c.seq, c.ingested_at, c.row_image, CASE WHEN c.op = 'update' THEN json_object_keys(c.row_image) END AS image_columns
  FROM goodparty_data_catalog.gp_api_mirror_dms.dms_cdc_change c CROSS JOIN reload r
  WHERE c.source_schema = 'public' AND c.source_table = 'replication_probe'
    AND (r.reloaded_at IS NULL OR c.ingested_at >= r.reloaded_at)
),
latest AS (
  SELECT
    max_by(op, seq) AS _dms_op,
    max(ingested_at) AS _dms_ingested_at,
    max_by(CAST(row_image:['id']::string AS BIGINT), seq) AS `id`,
    max_by(row_image:['payload']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'payload') THEN seq END) AS `payload`,
    max_by(row_image:['doc']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'doc') THEN seq END) AS `doc`,
    max_by(CAST(concat(regexp_replace(row_image:['updated_at']::string, '(Z|[+-]00(:?00)?)$', ''), '+00:00') AS TIMESTAMP), seq) AS `updated_at`
  FROM changes
  GROUP BY pk
)
SELECT `id`, `payload`, `doc`, `updated_at`, _dms_ingested_at
FROM latest
WHERE _dms_op <> 'delete';
